// Changes:
// New: checks one function: sets up the per-function part of the pass state
// (parameters take the slots 0..n-1) and walks the body.
static void check_def(Ctx* ctx, Sema* sema, AstNode* def) {
  AstNode* rettype = NULL;
  ast_node_get_child(ctx, def, DEF_RETTYPE, &rettype);
  size_t param_count = 0;
  if (ast_node_get_child_count(def) > DEF_PARAM_LIST) {
    AstNode* params = NULL;
    ast_node_get_child(ctx, def, DEF_PARAM_LIST, &params);
    param_count = ast_node_get_child_count(params);
  }

  sema->def = def;
  sema->next_slot = param_count;
  sema->return_declared = ast_node_get_type(rettype) != AST_NODE_NONE;
  check_body(ctx, sema);
  sema->def = NULL;
}

// AI generated by: Claude Code (claude-sonnet-5-5)
// Prompt: "implementation done using skill: mattpocock-skills:implement-spec,
// ticket 02: tracer, semantic entry point, member entries and function
